package com.gratilo.user.service;
import com.gratilo.user.domain.*; import com.gratilo.user.repository.*; import io.micronaut.context.annotation.Value; import jakarta.inject.Singleton; import jakarta.transaction.Transactional; import java.time.OffsetDateTime;
@Singleton public class PaymentUrlPoolService { private final PaymentUrlRepository urls; private final UserRepository users; private final EmailSendService email; private final String base;
 public PaymentUrlPoolService(PaymentUrlRepository urls,UserRepository users,EmailSendService email,@Value("${frontend.base-url:`http://localhost:3000`}") String base){this.urls=urls;this.users=users;this.email=email;this.base=base.replaceAll("/$","");}
 @Transactional public synchronized String assign(UserEntity user){long usedBefore=urls.countByAssignedUserIdIsNotNull();var old=urls.findByAssignedUserId(user.getId()); if(old.isPresent())return old.get().getPaymentUrl(); var slot=urls.findFirstByAssignedUserIdIsNullOrderById().orElseThrow(()->new IllegalStateException("Der Gratilo-URL-Pool ist ausgeschöpft.")); slot.setAssignedUserId(user.getId()); slot.setAssignedAt(OffsetDateTime.now()); slot.setPaymentUrl(url(String.format("gratilo-%03d", slot.getId()))); urls.update(slot);long used=urls.countByAssignedUserIdIsNotNull();if(usedBefore<80&&used>=80){email.sendText("info@gratilo.de","Gratilo-URL-Pool zu 80 % belegt","Der Pool ist zu mindestens 80 % vergeben ("+used+" von 100). Bitte neue URLs anlegen.");}return slot.getPaymentUrl();}
 public String url(String path){return base+"/pay/"+path;} public UserEntity userForPath(String path){return urls.findByPaymentUrl(url(path)).flatMap(x->x.getAssignedUserId()==null?java.util.Optional.empty():users.findById(x.getAssignedUserId()).filter(u->u.getDeletedAt()==null)).orElse(null);}
}
